// Auto-generated by fpga_autopilot — Strict Synthesizable SystemVerilog-2012
// Parameterized tick divider + 2-FF synchronizer + debouncer + Moore Traffic FSM

module traffic_fsm #(
    parameter [31:0] SIM_MODE          = 32'd0,
    parameter [31:0] CLK_FREQ_HZ       = 32'd50000000,
    parameter [31:0] SIM_TICKS_PER_SEC = 32'd4,
    parameter [3:0]  GREEN_SEC         = 4'd6,
    parameter [3:0]  YELLOW_SEC        = 4'd2,
    parameter [3:0]  PED_SEC           = 4'd4,
    parameter [3:0]  ALL_RED_SEC       = 4'd1
) (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       ped_btn_raw,
    input  logic       emergency_ovr,
    output logic [2:0] ns_light,
    output logic [2:0] ew_light,
    output logic       ped_walk,
    output logic [3:0] countdown
);

    typedef enum logic [2:0] {
        ST_NS_GREEN  = 3'd0,
        ST_NS_YELLOW = 3'd1,
        ST_ALL_RED_1 = 3'd2,
        ST_EW_GREEN  = 3'd3,
        ST_EW_YELLOW = 3'd4,
        ST_ALL_RED_2 = 3'd5,
        ST_PED_WALK  = 3'd6,
        ST_EMERGENCY = 3'd7
    } state_t;

    localparam [31:0] TICKS_PER_SEC = (SIM_MODE != 32'd0) ? SIM_TICKS_PER_SEC : CLK_FREQ_HZ;
    localparam [31:0] DEBOUNCE_MAX  = (SIM_MODE != 32'd0) ? 32'd2 : (CLK_FREQ_HZ / 32'd100);

    localparam [2:0] LIGHT_RED    = 3'b100;
    localparam [2:0] LIGHT_YELLOW = 3'b010;
    localparam [2:0] LIGHT_GREEN  = 3'b001;

    state_t      state, next_state;
    logic [31:0] tick_cnt;
    logic        sec_tick;
    logic        phase_done;
    logic [3:0]  timer_sec;
    logic [3:0]  next_duration;

    // 2-FF synchronizer + debouncer for asynchronous pedestrian button
    logic        ped_sync_ff1;
    logic        ped_sync_ff2;
    logic [31:0] db_cnt;
    logic        ped_debounced;
    logic        ped_debounced_d;
    logic        ped_pulse;
    logic        ped_pending;
    logic        resume_to_ew;

    // 2-FF Synchronizer & Counter-Based Debouncer
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ped_sync_ff1    <= 1'b0;
            ped_sync_ff2    <= 1'b0;
            db_cnt          <= 32'd0;
            ped_debounced   <= 1'b0;
            ped_debounced_d <= 1'b0;
        end else begin
            ped_sync_ff1    <= ped_btn_raw;
            ped_sync_ff2    <= ped_sync_ff1;
            ped_debounced_d <= ped_debounced;

            if (ped_sync_ff2 == ped_debounced) begin
                db_cnt <= 32'd0;
            end else if (db_cnt >= (DEBOUNCE_MAX - 32'd1)) begin
                db_cnt        <= 32'd0;
                ped_debounced <= ped_sync_ff2;
            end else begin
                db_cnt <= db_cnt + 32'd1;
            end
        end
    end

    always_comb begin
        ped_pulse  = 1'b0;
        sec_tick   = 1'b0;
        phase_done = 1'b0;

        ped_pulse  = ped_debounced && !ped_debounced_d;
        sec_tick   = (tick_cnt == (TICKS_PER_SEC - 32'd1));
        phase_done = sec_tick && (timer_sec <= 4'd1);
    end

    // Pedestrian Request Latch & Fair Direction Resume Memory
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            ped_pending  <= 1'b0;
            resume_to_ew <= 1'b1;
        end else begin
            if (emergency_ovr || (state == ST_PED_WALK)) begin
                ped_pending <= 1'b0;
            end else if (ped_pulse || ped_debounced) begin
                ped_pending <= 1'b1;
            end

            if (state == ST_ALL_RED_1) begin
                resume_to_ew <= 1'b1;
            end else if (state == ST_ALL_RED_2) begin
                resume_to_ew <= 1'b0;
            end
        end
    end

    // FSM State Register
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= ST_NS_GREEN;
        end else begin
            state <= next_state;
        end
    end

    // Parameterized Tick Generator & Countdown Timer
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            tick_cnt  <= 32'd0;
            timer_sec <= GREEN_SEC;
        end else if (emergency_ovr) begin
            tick_cnt  <= 32'd0;
            timer_sec <= 4'd0;
        end else if (state != next_state) begin
            tick_cnt  <= 32'd0;
            timer_sec <= next_duration;
        end else if (sec_tick) begin
            tick_cnt <= 32'd0;
            if (timer_sec > 4'd1) begin
                timer_sec <= timer_sec - 4'd1;
            end
        end else begin
            tick_cnt <= tick_cnt + 32'd1;
        end
    end

    // Next-State & Next-Phase-Duration Combinational Logic
    always_comb begin
        next_state    = state;
        next_duration = GREEN_SEC;

        if (emergency_ovr) begin
            next_state    = ST_EMERGENCY;
            next_duration = 4'd0;
        end else begin
            case (state)
                ST_NS_GREEN: begin
                    if (phase_done) begin
                        next_state    = ST_NS_YELLOW;
                        next_duration = YELLOW_SEC;
                    end
                end
                ST_NS_YELLOW: begin
                    if (phase_done) begin
                        next_state    = ST_ALL_RED_1;
                        next_duration = ALL_RED_SEC;
                    end
                end
                ST_ALL_RED_1: begin
                    if (phase_done) begin
                        if (ped_pending) begin
                            next_state    = ST_PED_WALK;
                            next_duration = PED_SEC;
                        end else begin
                            next_state    = ST_EW_GREEN;
                            next_duration = GREEN_SEC;
                        end
                    end
                end
                ST_EW_GREEN: begin
                    if (phase_done) begin
                        next_state    = ST_EW_YELLOW;
                        next_duration = YELLOW_SEC;
                    end
                end
                ST_EW_YELLOW: begin
                    if (phase_done) begin
                        next_state    = ST_ALL_RED_2;
                        next_duration = ALL_RED_SEC;
                    end
                end
                ST_ALL_RED_2: begin
                    if (phase_done) begin
                        if (ped_pending) begin
                            next_state    = ST_PED_WALK;
                            next_duration = PED_SEC;
                        end else begin
                            next_state    = ST_NS_GREEN;
                            next_duration = GREEN_SEC;
                        end
                    end
                end
                ST_PED_WALK: begin
                    if (phase_done) begin
                        if (resume_to_ew) begin
                            next_state    = ST_EW_GREEN;
                            next_duration = GREEN_SEC;
                        end else begin
                            next_state    = ST_NS_GREEN;
                            next_duration = GREEN_SEC;
                        end
                    end
                end
                ST_EMERGENCY: begin
                    next_state    = ST_ALL_RED_1;
                    next_duration = ALL_RED_SEC;
                end
                default: begin
                    next_state    = ST_NS_GREEN;
                    next_duration = GREEN_SEC;
                end
            endcase
        end
    end

    // Glitch-Free Pure Moore Output Logic
    always_comb begin
        ns_light  = LIGHT_RED;
        ew_light  = LIGHT_RED;
        ped_walk  = 1'b0;
        countdown = timer_sec;

        case (state)
            ST_NS_GREEN: begin
                ns_light = LIGHT_GREEN;
                ew_light = LIGHT_RED;
                ped_walk = 1'b0;
            end
            ST_NS_YELLOW: begin
                ns_light = LIGHT_YELLOW;
                ew_light = LIGHT_RED;
                ped_walk = 1'b0;
            end
            ST_ALL_RED_1: begin
                ns_light = LIGHT_RED;
                ew_light = LIGHT_RED;
                ped_walk = 1'b0;
            end
            ST_EW_GREEN: begin
                ns_light = LIGHT_RED;
                ew_light = LIGHT_GREEN;
                ped_walk = 1'b0;
            end
            ST_EW_YELLOW: begin
                ns_light = LIGHT_RED;
                ew_light = LIGHT_YELLOW;
                ped_walk = 1'b0;
            end
            ST_ALL_RED_2: begin
                ns_light = LIGHT_RED;
                ew_light = LIGHT_RED;
                ped_walk = 1'b0;
            end
            ST_PED_WALK: begin
                ns_light = LIGHT_RED;
                ew_light = LIGHT_RED;
                ped_walk = 1'b1;
            end
            ST_EMERGENCY: begin
                ns_light  = LIGHT_RED;
                ew_light  = LIGHT_RED;
                ped_walk  = 1'b0;
                countdown = 4'd0;
            end
            default: begin
                ns_light  = LIGHT_RED;
                ew_light  = LIGHT_RED;
                ped_walk  = 1'b0;
                countdown = 4'd0;
            end
        endcase
    end

endmodule

