\section{Tổng Quan Thiết Kế \& Đặc Tả Cổng Giao Tiếp (Port Specification)}
Synchronous smart intersection controller featuring a parameterized 50 MHz / SIM\_MODE 1-Hz tick divider, 2-FF asynchronous input synchronizer and counter debouncer for pedestrian button requests, emergency all-red override, countdown display, and glitch-free Moore traffic outputs.

\begin{table}[H]
    \centering
    \small
    \caption{Bảng đặc tả giao diện cổng vào/ra của module \texttt{traffic\_fsm}}
    \begin{tabularx}{\textwidth}{@{}llllX@{}}
        \toprule
        \textbf{Port} & \textbf{Dir} & \textbf{Width} & \textbf{Type} & \textbf{Chức năng (Description)} \\
        \midrule
        \texttt{clk} & input & 1 & logic & 50 MHz system clock \\
        \texttt{rst\_n} & input & 1 & active-low & Asynchronous active-low system reset \\
        \texttt{ped\_btn\_raw} & input & 1 & logic & Asynchronous pedestrian request push-button \\
        \texttt{emergency\_ovr} & input & 1 & logic & Synchronous high-priority emergency all-red override \\
        \texttt{ns\_light} & output & 3 & logic & North-South \{Red, Yellow, Green\} one-hot lamp bus \\
        \texttt{ew\_light} & output & 3 & logic & East-West \{Red, Yellow, Green\} one-hot lamp bus \\
        \texttt{ped\_walk} & output & 1 & logic & Pedestrian WALK indicator \\
        \texttt{countdown} & output & 4 & logic & Remaining seconds in active phase \\
        \bottomrule
    \end{tabularx}
\end{table}

\section{Finite State Machine Transition Table}
\begin{table}[H]
    \centering
    \small
    \caption{Synchronous Moore FSM State Encoding and Transitions}
    \begin{tabularx}{\textwidth}{@{}llXX@{}}
        \toprule
        \textbf{State} & \textbf{Code} & \textbf{Moore Outputs} & \textbf{Transition Condition} \\
        \midrule
        \texttt{ST\_NS\_GREEN} & 3'd0 & ns\_light=GREEN (001), ew\_light=RED (100), ped\_walk=0 & emergency\_ovr -> ST\_EMERGENCY; phase\_done -> ST\_NS\_YELLOW \\
        \texttt{ST\_NS\_YELLOW} & 3'd1 & ns\_light=YELLOW (010), ew\_light=RED (100), ped\_walk=0 & emergency\_ovr -> ST\_EMERGENCY; phase\_done -> ST\_ALL\_RED\_1 \\
        \texttt{ST\_ALL\_RED\_1} & 3'd2 & ns\_light=RED (100), ew\_light=RED (100), ped\_walk=0 & phase\_done \& ped\_pending -> ST\_PED\_WALK; phase\_done \& !ped\_pending -> ST\_EW\_GREEN \\
        \texttt{ST\_EW\_GREEN} & 3'd3 & ns\_light=RED (100), ew\_light=GREEN (001), ped\_walk=0 & emergency\_ovr -> ST\_EMERGENCY; phase\_done -> ST\_EW\_YELLOW \\
        \texttt{ST\_EW\_YELLOW} & 3'd4 & ns\_light=RED (100), ew\_light=YELLOW (010), ped\_walk=0 & emergency\_ovr -> ST\_EMERGENCY; phase\_done -> ST\_ALL\_RED\_2 \\
        \texttt{ST\_ALL\_RED\_2} & 3'd5 & ns\_light=RED (100), ew\_light=RED (100), ped\_walk=0 & phase\_done \& ped\_pending -> ST\_PED\_WALK; phase\_done \& !ped\_pending -> ST\_NS\_GREEN \\
        \texttt{ST\_PED\_WALK} & 3'd6 & ns\_light=RED (100), ew\_light=RED (100), ped\_walk=1 & phase\_done \& resume\_to\_ew -> ST\_EW\_GREEN; phase\_done \& !resume\_to\_ew -> ST\_NS\_GREEN \\
        \texttt{ST\_EMERGENCY} & 3'd7 & ns\_light=RED (100), ew\_light=RED (100), ped\_walk=0 & !emergency\_ovr -> ST\_ALL\_RED\_1 \\
        \bottomrule
    \end{tabularx}
\end{table}


\section{Triển Khai RTL SystemVerilog Chuẩn Tổng Hợp (Synthesizable RTL)}
Thiết kế tuân thủ nghiêm ngặt quy tắc SystemVerilog-2012: sử dụng \texttt{always\_ff} với phép gán không chặn (\texttt{<=}) cho mạch tuần tự, \texttt{always\_comb} với giá trị mặc định tường minh ở đầu khối cho mạch tổ hợp, cam kết \textbf{0 inferred latches}.

\begin{lstlisting}
// Auto-generated by fpga_autopilot — Strict Synthesizable SystemVerilog-2012
// Parameterized tick divider + 2-FF synchronizer + debouncer + Moore Traffic FSM

module traffic_fsm #(
    parameter [31:0] SIM_MODE          = 32'd0,
    parameter [31:0] CLK_FREQ_HZ       = 32'd50000000,
    parameter [31:0] SIM_TICKS_PER_SEC = 32'd4,
    parameter [3:0]  GREEN_SEC         = 4'd6,
    parameter [3:0]  YELLOW_SEC        = 4'd2,
    parameter [3:0]  PED_SEC           = 4'd4,
    parameter [3:0]  ALL_RED_SEC       = 4'd1
) (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       ped_btn_raw,
    input  logic       emergency_ovr,
    output logic [2:0] ns_light,
