// Auto-generated by fpga_autopilot — Parameterized Show-Ahead Circular Sync FIFO

module sync_fifo #(
    parameter DATA_WIDTH = 8,
    parameter ADDR_WIDTH = 3
) (
    input  logic                  clk,
    input  logic                  rst_n,
    input  logic                  wr_en,
    input  logic [DATA_WIDTH-1:0] wr_data,
    input  logic                  rd_en,
    output logic [DATA_WIDTH-1:0] rd_data,
    output logic                  full,
    output logic                  empty
);

    localparam DEPTH = (1 << ADDR_WIDTH);
    localparam [ADDR_WIDTH:0] FULL_COUNT  = {1'b1, {ADDR_WIDTH{1'b0}}};
    localparam [ADDR_WIDTH:0] EMPTY_COUNT = {(ADDR_WIDTH + 1){1'b0}};
    localparam [ADDR_WIDTH:0] ONE_COUNT   = {{ADDR_WIDTH{1'b0}}, 1'b1};
    localparam [ADDR_WIDTH-1:0] ONE_PTR   = {{(ADDR_WIDTH - 1){1'b0}}, 1'b1};

    logic [DATA_WIDTH-1:0] mem [0:DEPTH-1];
    logic [ADDR_WIDTH-1:0] wr_ptr;
    logic [ADDR_WIDTH-1:0] rd_ptr;
    logic [ADDR_WIDTH:0]   count;
    logic                  do_wr;
    logic                  do_rd;

    always_comb begin
        full    = (count == FULL_COUNT);
        empty   = (count == EMPTY_COUNT);
        rd_data = mem[rd_ptr];
    end

    always_comb begin
        do_wr = wr_en && !full;
        do_rd = rd_en && !empty;
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wr_ptr <= {ADDR_WIDTH{1'b0}};
            rd_ptr <= {ADDR_WIDTH{1'b0}};
            count  <= EMPTY_COUNT;
            for (int idx = 0; idx < DEPTH; idx = idx + 1) begin
                mem[idx] <= {DATA_WIDTH{1'b0}};
            end
        end else begin
            if (do_wr) begin
                mem[wr_ptr] <= wr_data;
                wr_ptr      <= wr_ptr + ONE_PTR;
            end
            if (do_rd) begin
                rd_ptr <= rd_ptr + ONE_PTR;
            end
            case ({do_wr, do_rd})
                2'b10:   count <= count + ONE_COUNT;
                2'b01:   count <= count - ONE_COUNT;
                default: count <= count;
            endcase
        end
    end

endmodule

// Auto-generated by fpga_autopilot — UART Transmitter FSM (8N1)

module uart_tx #(
    parameter [31:0] BIT_CLKS = 32'd432
) (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       fifo_empty,
    input  logic [7:0] fifo_data,
    output logic       fifo_pop,
    output logic       tx_serial,
    output logic       tx_busy
);

    typedef enum logic [1:0] {
        TX_IDLE  = 2'd0,
        TX_START = 2'd1,
        TX_DATA  = 2'd2,
        TX_STOP  = 2'd3
    } tx_state_t;

    tx_state_t   state, next_state;
    logic [31:0] clk_cnt;
    logic        bit_done;
    logic [2:0]  bit_idx;
    logic [7:0]  shift_reg;

    always_comb begin
        fifo_pop   = 1'b0;
        tx_serial  = 1'b1;
        tx_busy    = 1'b1;
        next_state = state;
        bit_done   = (clk_cnt == (BIT_CLKS - 32'd1));

        case (state)
            TX_IDLE: begin
                tx_serial = 1'b1;
                tx_busy   = 1'b0;
                if (!fifo_empty) begin
                    fifo_pop   = 1'b1;
                    next_state = TX_START;
                end
            end
            TX_START: begin
                tx_serial = 1'b0;
                tx_busy   = 1'b1;
                if (bit_done) begin
                    next_state = TX_DATA;
                end
            end
            TX_DATA: begin
                tx_serial = shift_reg[0];
                tx_busy   = 1'b1;
                if (bit_done && (bit_idx == 3'd7)) begin
                    next_state = TX_STOP;
                end
            end
            TX_STOP: begin
                tx_serial = 1'b1;
                tx_busy   = 1'b1;
                if (bit_done) begin
                    next_state = TX_IDLE;
                end
            end
            default: begin
                tx_serial  = 1'b1;
                tx_busy    = 1'b0;
                next_state = TX_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state     <= TX_IDLE;
            clk_cnt   <= 32'd0;
            bit_idx   <= 3'd0;
            shift_reg <= 8'd0;
        end else begin
            state <= next_state;
            case (state)
                TX_IDLE: begin
                    clk_cnt <= 32'd0;
                    bit_idx <= 3'd0;
                    if (!fifo_empty) begin
                        shift_reg <= fifo_data;
                    end
                end
                TX_START: begin
                    if (bit_done) begin
                        clk_cnt <= 32'd0;
                        bit_idx <= 3'd0;
                    end else begin
                        clk_cnt <= clk_cnt + 32'd1;
                    end
                end
                TX_DATA: begin
                    if (bit_done) begin
                        clk_cnt   <= 32'd0;
                        shift_reg <= {1'b0, shift_reg[7:1]};
                        if (bit_idx != 3'd7) begin
                            bit_idx <= bit_idx + 3'd1;
                        end
                    end else begin
                        clk_cnt <= clk_cnt + 32'd1;
                    end
                end
                TX_STOP: begin
                    if (bit_done) begin
                        clk_cnt <= 32'd0;
                    end else begin
                        clk_cnt <= clk_cnt + 32'd1;
                    end
                end
                default: begin
                    clk_cnt <= 32'd0;
                end
            endcase
        end
    end

endmodule

// Auto-generated by fpga_autopilot — UART Receiver FSM with 16x Oversampling

module uart_rx #(
    parameter [31:0] OS_DIV = 32'd27
) (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       rx_serial,
    input  logic       clr_err,
    output logic       rx_valid,
    output logic [7:0] rx_byte,
    output logic       framing_error
);

    typedef enum logic [2:0] {
        RX_IDLE     = 3'd0,
        RX_START    = 3'd1,
        RX_DATA     = 3'd2,
        RX_STOP     = 3'd3,
        RX_ERR_WAIT = 3'd4
    } rx_state_t;

    rx_state_t   state, next_state;
    logic        rx_ff1;
    logic        rx_sync;
    logic [31:0] div_cnt;
    logic        os_tick;
    logic [3:0]  os_cnt;
    logic [2:0]  bit_idx;
    logic [7:0]  shift_reg;

    // 2-FF input synchronizer (idle UART line is logic HIGH)
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            rx_ff1  <= 1'b1;
            rx_sync <= 1'b1;
        end else begin
            rx_ff1  <= rx_serial;
            rx_sync <= rx_ff1;
        end
    end

    always_comb begin
        os_tick    = 1'b0;
        next_state = state;

        os_tick = (div_cnt == (OS_DIV - 32'd1));

        case (state)
            RX_IDLE: begin
                if (!rx_sync) begin
                    next_state = RX_START;
                end
            end
            RX_START: begin
                if (os_tick && (os_cnt == 4'd7)) begin
                    if (!rx_sync) begin
                        next_state = RX_DATA;
                    end else begin
                        next_state = RX_IDLE;
                    end
                end
            end
            RX_DATA: begin
                if (os_tick && (os_cnt == 4'd15) && (bit_idx == 3'd7)) begin
                    next_state = RX_STOP;
                end
            end
            RX_STOP: begin
                if (os_tick && (os_cnt == 4'd15)) begin
                    if (rx_sync) begin
                        next_state = RX_IDLE;
                    end else begin
                        next_state = RX_ERR_WAIT;
                    end
                end
            end
            RX_ERR_WAIT: begin
                if (rx_sync) begin
                    next_state = RX_IDLE;
                end
            end
            default: begin
                next_state = RX_IDLE;
            end
        endcase
    end

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state         <= RX_IDLE;
            div_cnt       <= 32'd0;
            os_cnt        <= 4'd0;
            bit_idx       <= 3'd0;
            shift_reg     <= 8'd0;
            rx_byte       <= 8'd0;
            rx_valid      <= 1'b0;
            framing_error <= 1'b0;
        end else begin
            state    <= next_state;
            rx_valid <= 1'b0;

            if (clr_err) begin
                framing_error <= 1'b0;
            end

            case (state)
                RX_IDLE: begin
                    div_cnt <= 32'd0;
                    os_cnt  <= 4'd0;
                    bit_idx <= 3'd0;
                end
                RX_START: begin
                    if (os_tick) begin
                        div_cnt <= 32'd0;
                        if (os_cnt == 4'd7) begin
                            os_cnt <= 4'd0;
                        end else begin
                            os_cnt <= os_cnt + 4'd1;
                        end
                    end else begin
                        div_cnt <= div_cnt + 32'd1;
                    end
                end
                RX_DATA: begin
                    if (os_tick) begin
                        div_cnt <= 32'd0;
                        if (os_cnt == 4'd15) begin
                            os_cnt    <= 4'd0;
                            shift_reg <= {rx_sync, shift_reg[7:1]};
                            if (bit_idx != 3'd7) begin
                                bit_idx <= bit_idx + 3'd1;
                            end
                        end else begin
                            os_cnt <= os_cnt + 4'd1;
                        end
                    end else begin
                        div_cnt <= div_cnt + 32'd1;
                    end
                end
                RX_STOP: begin
                    if (os_tick) begin
                        div_cnt <= 32'd0;
                        if (os_cnt == 4'd15) begin
                            os_cnt <= 4'd0;
                            if (rx_sync) begin
                                rx_byte  <= shift_reg;
                                rx_valid <= 1'b1;
                            end else begin
                                framing_error <= 1'b1;
                            end
                        end else begin
                            os_cnt <= os_cnt + 4'd1;
                        end
                    end else begin
                        div_cnt <= div_cnt + 32'd1;
                    end
                end
                RX_ERR_WAIT: begin
                    div_cnt <= 32'd0;
                    os_cnt  <= 4'd0;
                end
                default: begin
                    div_cnt <= 32'd0;
                    os_cnt  <= 4'd0;
                end
            endcase
        end
    end

