    logic       loopback_en;
    logic       manual_rx;

    logic [7:0] tx_vec [0:63];
    integer     tx_idx;
    integer     rx_idx;
    integer     passed_cnt;
    integer     failed_cnt;
    integer     cycle_cnt;
    integer     guard_Wait;

    assign rx_serial = loopback_en ? tx_serial : manual_rx;

    uart_fifo_top #(
        .CLK_FREQ  (SIM_CLK_FREQ),
        .BAUD_RATE (SIM_BAUD_RATE)
    ) dut (
        .clk           (clk),
        .rst_n         (rst_n),
