\section{Triển Khai RTL SystemVerilog Chuẩn Tổng Hợp (Synthesizable RTL)}
Thiết kế tuân thủ nghiêm ngặt quy tắc SystemVerilog-2012: sử dụng \texttt{always\_ff} với phép gán không chặn (\texttt{<=}) cho mạch tuần tự, \texttt{always\_comb} với giá trị mặc định tường minh ở đầu khối cho mạch tổ hợp, cam kết \textbf{0 inferred latches}.

\begin{lstlisting}
// Auto-generated by fpga_autopilot — Configurable UART TX/RX Transceiver + 8-Byte Sync FIFO

module uart_fifo_top #(
    parameter [31:0] CLK_FREQ  = 32'd50000000,
    parameter [31:0] BAUD_RATE = 32'd115200
) (
    input  logic       clk,
    input  logic       rst_n,
    input  logic       wr_en,
    input  logic [7:0] wr_data,
    input  logic       rd_en,
    input  logic       rx_serial,
    input  logic       clr_err,
    output logic       tx_serial,
    output logic [7:0] rd_data,
    output logic       tx_full,
    output logic       tx_empty,
    output logic       rx_full,
    output logic       rx_empty,
    output logic       tx_busy,
    output logic       framing_error
);

    localparam [31:0] OS_DIV_RAW = CLK_FREQ / (BAUD_RATE * 32'd16);
    localparam [31:0] OS_DIV     = (OS_DIV_RAW == 32'd0) ? 32'd1 : OS_DIV_RAW;
    localparam [31:0] BIT_CLKS   = OS_DIV * 32'd16;

    logic [7:0] tx_fifo_dout;
    logic       tx_fifo_pop;
    logic       rx_valid;
    logic [7:0] rx_byte;
    logic       rx_fifo_wr;

    always_comb begin
        rx_fifo_wr = rx_valid && !rx_full;
    end

    sync_fifo #(
        .DATA_WIDTH (8),
        .ADDR_WIDTH (3)
    ) u_tx_fifo (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .rd_en   (tx_fifo_pop),
        .rd_data (tx_fifo_dout),
        .full    (tx_full),
        .empty   (tx_empty)
    );

    uart_tx #(
        .BIT_CLKS (BIT_CLKS)
    ) u_uart_tx (
        .clk        (clk),
        .rst_n      (rst_n),
        .fifo_empty (tx_empty),
        .fifo_data  (tx_fifo_dout),
// ... (truncated for report conciseness; full source in rtl/ directory)
